var ids=['signin','new-conversation','conversation','conversation--approval','conversation--menu','conversation--delete','search','activity','activity--work'];
['Light/Clean','Dark/Clean'].forEach(function(app){var p=H.page('Proto macOS '+app.split('/')[0]);ids.forEach(function(id){var ss=p.layers.filter(function(l){return l.name==='Screen/macos/'+app+'/'+id;});ss.forEach(function(s){var bad=[];var links=[];var bits=[];function visit(l){if(l.name.indexOf('link:')===0)links.push(l.name);if(['sidebar','toolbar','inspector','conversation-menu','scrim','alert'].indexOf(l.name)>=0)bits.push({name:l.name,w:l.frame.width,h:l.frame.height,x:l.frame.x,y:l.frame.y,index:l.index});(l.layers||[]).forEach(function(c){if(c.frame.y+c.frame.height>l.frame.height+1||c.frame.x+c.frame.width>l.frame.width+1)bad.push({parent:l.name,child:c.name,pw:l.frame.width,ph:l.frame.height,x:c.frame.x,y:c.frame.y,w:c.frame.width,h:c.frame.height});visit(c);});}visit(s);console.log(JSON.stringify({id:id,app:app,frame:s.id,count:ss.length,bits:bits,bad:bad,invalidLinks:links.filter(function(n){return / \d+$/.test(n);}),linkCount:links.length}));});});});
